INSERT INTO edu_curriculum_sources (code, title, document_no, issued_date, issuer, official_url, retrieved_from_url, retrieved_at, scope_note) VALUES ('VBHN-01-2021-GDMN', 'Văn bản hợp nhất Thông tư ban hành Chương trình giáo dục mầm non', '01/VBHN-BGDĐT', '2021-04-13', 'Bộ Giáo dục và Đào tạo', 'https://vbpl.vn/', 'https://caselaw.vn/van-ban-phap-luat/364454-van-ban-hop-nhat-so-01-vbhn-bgddt-ngay-13-04-2021-cua-bo-giao-duc-va-dao-tao-hop-nhat-thong-tu-ve-chuong-trinh-giao-duc-mam-non', '2026-10-28', 'Hợp nhất Thông tư 17/2009/TT-BGDĐT, 28/2016/TT-BGDĐT, 51/2020/TT-BGDĐT. Lấy nguyên văn mục D "Kết quả mong đợi" (câu đánh số thành mục tiêu, gạch đầu dòng thành nội dung, tiêu đề hàng thành nhóm kết quả mong đợi) và mục C "Nội dung giáo dục theo độ tuổi" (gợi ý nội dung) của: nhà trẻ cột 24–36 tháng (Phần hai), mẫu giáo cột 3–4, 4–5, 5–6 tuổi (Phần ba). Câu đang có hiệu lực; bỏ đoạn đã bãi bỏ. Nhà trẻ mục IV "Tình cảm, kỹ năng xã hội và thẩm mỹ" tách theo nhóm: hát, vận động theo nhạc, vẽ, nặn, xem tranh vào Phát triển thẩm mỹ, còn lại vào Phát triển tình cảm và kỹ năng xã hội. Tra văn bản gốc trên Cơ sở dữ liệu quốc gia về văn bản pháp luật theo số hiệu 01/VBHN-BGDĐT.');
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-2'), (SELECT id FROM edu_domains WHERE name = 'Phát triển thể chất'), 'Phát triển vận động', '1', 'Thực hiện động tác phát triển các nhóm cơ và hô hấp', NULL, 'Thực hiện được các động tác trong bài tập thể dục: hít thở, tay, lưng/bụng và chân.', 'Phần hai › D › I › a) › 1', 1);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-2'), (SELECT id FROM edu_domains WHERE name = 'Phát triển thể chất'), 'Phát triển vận động', '2', 'Thực hiện vận động cơ bản và phát triển tố chất vận động ban đầu', '2.1', 'Giữ được thăng bằng trong vận động đi/chạy thay đổi tốc độ nhanh - chậm theo cô hoặc đi trong đường hẹp có bê vật trên tay.', 'Phần hai › D › I › a) › 2 › 2.1', 2);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-2'), (SELECT id FROM edu_domains WHERE name = 'Phát triển thể chất'), 'Phát triển vận động', '2', 'Thực hiện vận động cơ bản và phát triển tố chất vận động ban đầu', '2.2', 'Thực hiện phối hợp vận động tay - mắt: tung - bắt bóng với cô ở khoảng cách 1m; ném vào đích xa 1 - 1,2m.', 'Phần hai › D › I › a) › 2 › 2.2', 3);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-2'), (SELECT id FROM edu_domains WHERE name = 'Phát triển thể chất'), 'Phát triển vận động', '2', 'Thực hiện vận động cơ bản và phát triển tố chất vận động ban đầu', '2.3', 'Phối hợp tay, chân, cơ thể trong khi bò để giữ được vật đặt trên lưng.', 'Phần hai › D › I › a) › 2 › 2.3', 4);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-2'), (SELECT id FROM edu_domains WHERE name = 'Phát triển thể chất'), 'Phát triển vận động', '2', 'Thực hiện vận động cơ bản và phát triển tố chất vận động ban đầu', '2.4', 'Thể hiện sức mạnh của cơ bắp trong vận động ném, đá bóng: ném xa lên phía trước bằng một tay (tối thiểu 1,5m).', 'Phần hai › D › I › a) › 2 › 2.4', 5);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-2'), (SELECT id FROM edu_domains WHERE name = 'Phát triển thể chất'), 'Phát triển vận động', '3', 'Thực hiện vận động cử động của bàn tay, ngón tay', '3.1', 'Vận động cổ tay, bàn tay, ngón tay - thực hiện “múa khéo”.', 'Phần hai › D › I › a) › 3 › 3.1', 6);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-2'), (SELECT id FROM edu_domains WHERE name = 'Phát triển thể chất'), 'Phát triển vận động', '3', 'Thực hiện vận động cử động của bàn tay, ngón tay', '3.2', 'Phối hợp được cử động bàn tay, ngón tay và phối hợp tay -mắt trong các hoạt động: nhào đất nặn; vẽ tổ chim; xâu vòng tay, chuỗi đeo cổ.', 'Phần hai › D › I › a) › 3 › 3.2', 7);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-2'), (SELECT id FROM edu_domains WHERE name = 'Phát triển thể chất'), 'Giáo dục dinh dưỡng và sức khỏe', '1', 'Có một số nền nếp, thói quen tốt trong sinh hoạt', '1.1', 'Thích nghi với chế độ ăn cơm, ăn được các loại thức ăn khác nhau.', 'Phần hai › D › I › b) › 1 › 1.1', 8);
