INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-2'), (SELECT id FROM edu_domains WHERE name = 'Phát triển thể chất'), 'Giáo dục dinh dưỡng và sức khỏe', '3', 'Nhận biết và tránh một số nguy cơ không an toàn', '3.2', 'Biết và tránh một số hành động nguy hiểm (leo trèo lên lan can, chơi nghịch các vật sắc nhọn,...) khi được nhắc nhở.', 'Phần hai › D › I › b) › 3 › 3.2', 14);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-2'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), NULL, '1', 'Khám phá thế giới xung quanh bằng các giác quan', NULL, 'Sờ nắn, nhìn, nghe, ngửi, nếm để nhận biết đặc điểm nổi bật của đối tượng.', 'Phần hai › D › II › 1', 15);
