INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-2'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), NULL, '2', 'Thể hiện sự hiểu biết về các sự vật, hiện tượng gần gũi', '2.3', 'Nói được tên và chức năng của một số bộ phận cơ thể khi được hỏi.', 'Phần hai › D › II › 2 › 2.3', 18);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-2'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), NULL, '2', 'Thể hiện sự hiểu biết về các sự vật, hiện tượng gần gũi', '2.4', 'Nói được tên và một vài đặc điểm nổi bật của các đồ vật, hoa quả, con vật quen thuộc.', 'Phần hai › D › II › 2 › 2.4', 19);
