INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-2'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), NULL, '2', 'Thể hiện sự hiểu biết về các sự vật, hiện tượng gần gũi', '2.6', 'Chỉ hoặc lấy hoặc cất đúng đồ chơi có kích thước to/nhỏ theo yêu cầu.', 'Phần hai › D › II › 2 › 2.6', 21);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-2'), (SELECT id FROM edu_domains WHERE name = 'Phát triển ngôn ngữ'), NULL, '1', 'Nghe hiểu lời nói', '1.1', 'Thực hiện được nhiệm vụ gồm 2 - 3 hành động. Ví dụ: Cháu cất đồ chơi lên giá rồi đi rửa tay.', 'Phần hai › D › III › 1 › 1.1', 22);
