INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-4'), (SELECT id FROM edu_domains WHERE name = 'Phát triển thể chất'), 'Giáo dục dinh dưỡng và sức khỏe', '4', 'Biết một số nguy cơ không an toàn và phòng tránh', '4.2', 'Nhận ra những nơi như: hồ, ao, mương nước, suối, bể chứa nước… là nơi nguy hiểm, không được chơi gần.', 'Phần ba › D › I › b) › 4 › 4.2', 16);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-4'), (SELECT id FROM edu_domains WHERE name = 'Phát triển thể chất'), 'Giáo dục dinh dưỡng và sức khỏe', '4', 'Biết một số nguy cơ không an toàn và phòng tránh', '4.3', 'Biết một số hành động nguy hiểm và phòng tránh khi được nhắc nhở', 'Phần ba › D › I › b) › 4 › 4.3', 17);
INSERT INTO edu_curriculum_goal_contents (curriculum_goal_id, text, sort_order) VALUES ((SELECT id FROM edu_curriculum_goals WHERE source_id = (SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN') AND age_group_id = (SELECT id FROM age_groups WHERE code = 'ag-4') AND sort_order = 17), 'Không cười đùa trong khi ăn, uống hoặc khi ăn các loại quả có hạt....', 0);
INSERT INTO edu_curriculum_goal_contents (curriculum_goal_id, text, sort_order) VALUES ((SELECT id FROM edu_curriculum_goals WHERE source_id = (SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN') AND age_group_id = (SELECT id FROM age_groups WHERE code = 'ag-4') AND sort_order = 17), 'Không ăn thức ăn có mùi ôi; không ăn lá, quả lạ... không uống rượu, bia, cà phê; không tự ý uống thuốc khi không được phép của người lớn.', 1);
INSERT INTO edu_curriculum_goal_contents (curriculum_goal_id, text, sort_order) VALUES ((SELECT id FROM edu_curriculum_goals WHERE source_id = (SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN') AND age_group_id = (SELECT id FROM age_groups WHERE code = 'ag-4') AND sort_order = 17), 'Không được ra khỏi trường khi không được phép của cô giáo.', 2);
