INSERT INTO edu_curriculum_goal_contents (curriculum_goal_id, text, sort_order) VALUES ((SELECT id FROM edu_curriculum_goals WHERE source_id = (SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN') AND age_group_id = (SELECT id FROM age_groups WHERE code = 'ag-4') AND sort_order = 18), 'Biết gọi người lớn khi gặp một số trường hợp khẩn cấp: cháy, có người rơi xuống nước, ngã chảy máu.', 0);
INSERT INTO edu_curriculum_goal_contents (curriculum_goal_id, text, sort_order) VALUES ((SELECT id FROM edu_curriculum_goals WHERE source_id = (SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN') AND age_group_id = (SELECT id FROM age_groups WHERE code = 'ag-4') AND sort_order = 18), 'Biết gọi người giúp đỡ khi bị lạc. Nói được tên, địa chỉ gia đình, số điện thoại người thân khi cần thiết.', 1);
