INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển thể chất'), 'Giáo dục dinh dưỡng và sức khỏe', '1', 'Biết một số món ăn, thực phẩm thông thường và ích lợi của chúng đối với sức khỏe', '1.3', 'Biết: ăn nhiều loại thức ăn, ăn chín, uống nước đun sôi để khỏe mạnh; uống nhiều nước ngọt, nước có gas, ăn nhiều đồ ngọt dễ béo phì không có lợi cho sức khỏe.', 'Phần ba › D › I › b) › 1 › 1.3', 9);
