INSERT INTO edu_curriculum_goal_contents (curriculum_goal_id, text, sort_order) VALUES ((SELECT id FROM edu_curriculum_goals WHERE source_id = (SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN') AND age_group_id = (SELECT id FROM age_groups WHERE code = 'ag-5') AND sort_order = 17), 'Khi người lạ bế ẵm, cho kẹo bánh, uống nước ngọt, rủ đi chơi.', 2);
INSERT INTO edu_curriculum_goal_contents (curriculum_goal_id, text, sort_order) VALUES ((SELECT id FROM edu_curriculum_goals WHERE source_id = (SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN') AND age_group_id = (SELECT id FROM age_groups WHERE code = 'ag-5') AND sort_order = 17), 'Ra khỏi nhà, khu vực trường, lớp khi không được phép của người lớn, cô giáo.', 3);
INSERT INTO edu_curriculum_goal_contents (curriculum_goal_id, text, sort_order) VALUES ((SELECT id FROM edu_curriculum_goals WHERE source_id = (SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN') AND age_group_id = (SELECT id FROM age_groups WHERE code = 'ag-5') AND sort_order = 17), 'Biết được địa chỉ nơi ở, số điện thoại gia đình, người thân và khi bị lạc biết hỏi, gọi người lớn giúp đỡ.', 4);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển thể chất'), 'Giáo dục dinh dưỡng và sức khỏe', '4', 'Biết một số nguy cơ không an toàn và phòng tránh', '4.5', 'Thực hiện một số quy định ở trường, nơi công cộng về an toàn', 'Phần ba › D › I › b) › 4 › 4.5', 18);
INSERT INTO edu_curriculum_goal_contents (curriculum_goal_id, text, sort_order) VALUES ((SELECT id FROM edu_curriculum_goals WHERE source_id = (SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN') AND age_group_id = (SELECT id FROM age_groups WHERE code = 'ag-5') AND sort_order = 18), 'Sau giờ học về nhà ngay, không tự ý đi chơi.', 0);
INSERT INTO edu_curriculum_goal_contents (curriculum_goal_id, text, sort_order) VALUES ((SELECT id FROM edu_curriculum_goals WHERE source_id = (SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN') AND age_group_id = (SELECT id FROM age_groups WHERE code = 'ag-5') AND sort_order = 18), 'Đi bộ trên hè; đi sang đường phải có người lớn dắt; đội mũ an toàn khi ngồi trên xe máy.', 1);
INSERT INTO edu_curriculum_goal_contents (curriculum_goal_id, text, sort_order) VALUES ((SELECT id FROM edu_curriculum_goals WHERE source_id = (SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN') AND age_group_id = (SELECT id FROM age_groups WHERE code = 'ag-5') AND sort_order = 18), 'Không leo trèo cây, ban công, tường rào...', 2);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-3'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '1', 'Xem xét và tìm hiểu đặc điểm của các sự vật, hiện tượng', '1.1', 'Quan tâm, hứng thú với các sự vật, hiện tượng gần gũi, như chăm chú quan sát sự vật, hiện tượng; hay đặt câu hỏi về đối tượng.', 'Phần ba › D › II › a) › 1 › 1.1', 18);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-3'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '1', 'Xem xét và tìm hiểu đặc điểm của các sự vật, hiện tượng', '1.2', 'Sử dụng các giác quan để xem xét, tìm hiểu đối tượng: nhìn, nghe, ngửi, sờ,.. để nhận ra đặc điểm nổi bật của đối tượng.', 'Phần ba › D › II › a) › 1 › 1.2', 19);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-3'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '1', 'Xem xét và tìm hiểu đặc điểm của các sự vật, hiện tượng', '1.3', 'Làm thử nghiệm đơn giản với sự giúp đỡ của người lớn để quan sát, tìm hiểu đối tượng. Ví dụ: Thả các vật vào nước để nhận biết vật chìm hay nổi.', 'Phần ba › D › II › a) › 1 › 1.3', 20);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-3'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '1', 'Xem xét và tìm hiểu đặc điểm của các sự vật, hiện tượng', '1.4', 'Thu thập thông tin về đối tượng bằng nhiều cách khác nhau có sự gợi mở của cô giáo như xem sách, tranh ảnh và trò chuyện về đối tượng.', 'Phần ba › D › II › a) › 1 › 1.4', 21);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-3'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '1', 'Xem xét và tìm hiểu đặc điểm của các sự vật, hiện tượng', '1.5', 'Phân loại các đối tượng theo một dấu hiệu nổi bật.', 'Phần ba › D › II › a) › 1 › 1.5', 22);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-3'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '2', 'Nhận biết mối quan hệ đơn giản của sự vật, hiện tượng và giải quyết vấn đề đơn giản', NULL, 'Nhận ra một vài mối quan hệ đơn giản của sự vật, hiện tượng quen thuộc khi được hỏi.', 'Phần ba › D › II › a) › 2', 23);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-3'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '3', 'Thể hiện hiểu biết về đối tượng bằng các cách khác nhau', '3.1', 'Mô tả những dấu hiệu nổi bật của đối tượng được quan sát với sự gợi mở của cô giáo.', 'Phần ba › D › II › a) › 3 › 3.1', 24);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-3'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '3', 'Thể hiện hiểu biết về đối tượng bằng các cách khác nhau', '3.2', 'Thể hiện một số điều quan sát được qua các hoạt động chơi, âm nhạc, tạo hình...', 'Phần ba › D › II › a) › 3 › 3.2', 25);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-4'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '1', 'Xem xét và tìm hiểu đặc điểm của các sự vật, hiện tượng', '1.1', 'Quan tâm đến những thay đổi của sự vật, hiện tượng xung quanh với sự gợi ý, hướng dẫn của cô giáo như đặt câu hỏi về những thay đổi của sự vật, hiện tượng: Vì sao cây lại héo? Vì sao lá cây bị ướt?....', 'Phần ba › D › II › a) › 1 › 1.1', 19);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-4'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '1', 'Xem xét và tìm hiểu đặc điểm của các sự vật, hiện tượng', '1.2', 'Phối hợp các giác quan để xem xét sự vật, hiện tượng như kết hợp nhìn, sờ, ngửi, nếm... để tìm hiểu đặc điểm của đối tượng.', 'Phần ba › D › II › a) › 1 › 1.2', 20);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-4'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '1', 'Xem xét và tìm hiểu đặc điểm của các sự vật, hiện tượng', '1.3', 'Làm thử nghiệm và sử dụng công cụ đơn giản để quan sát, so sánh, dự đoán. Ví dụ: Pha màu/đường/ muối vào nước, dự đoán, quan sát, so sánh.', 'Phần ba › D › II › a) › 1 › 1.3', 21);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-4'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '1', 'Xem xét và tìm hiểu đặc điểm của các sự vật, hiện tượng', '1.4', 'Thu thập thông tin về đối tượng bằng nhiều cách khác nhau: xem sách, tranh ảnh, nhận xét và trò chuyện.', 'Phần ba › D › II › a) › 1 › 1.4', 22);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-4'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '1', 'Xem xét và tìm hiểu đặc điểm của các sự vật, hiện tượng', '1.5', 'Phân loại các đối tượng theo một hoặc hai dấu hiệu.', 'Phần ba › D › II › a) › 1 › 1.5', 23);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-4'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '2', 'Nhận biết mối quan hệ đơn giản của sự vật, hiện tượng và giải quyết vấn đề đơn giản', '2.1', 'Nhận xét được một số mối quan hệ đơn giản của sự vật, hiện tượng gần gũi. Ví dụ: “Cho thêm đường/ muối nên nước ngọt/ mặn hơn”', 'Phần ba › D › II › a) › 2 › 2.1', 24);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-4'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '2', 'Nhận biết mối quan hệ đơn giản của sự vật, hiện tượng và giải quyết vấn đề đơn giản', '2.2', 'Sử dụng cách thức thích hợp để giải quyết vấn đề đơn giản. Ví dụ: Làm cho ván dốc hơn để ô tô đồ chơi chạy nhanh hơn.', 'Phần ba › D › II › a) › 2 › 2.2', 25);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-4'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '3', 'Thể hiện hiểu biết về đối tượng bằng các cách khác nhau', '3.1', 'Nhận xét, trò chuyện về đặc điểm, sự khác nhau, giống nhau của các đối tượng được quan sát.', 'Phần ba › D › II › a) › 3 › 3.1', 26);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-4'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '3', 'Thể hiện hiểu biết về đối tượng bằng các cách khác nhau', '3.2', 'Thể hiện một số hiểu biết về đối tượng qua hoạt động chơi, âm nhạc và tạo hình...', 'Phần ba › D › II › a) › 3 › 3.2', 27);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '1', 'Xem xét và tìm hiểu đặc điểm của các sự vật, hiện tượng', '1.1', 'Tò mò tìm tòi, khám phá các sự vật, hiện tượng xung quanh như đặt câu hỏi về sự vật, hiện tượng: Tại sao có mưa?...', 'Phần ba › D › II › a) › 1 › 1.1', 19);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '1', 'Xem xét và tìm hiểu đặc điểm của các sự vật, hiện tượng', '1.2', 'Phối hợp các giác quan để quan sát, xem xét và thảo luận về sự vật, hiện tượng như sử dụng các giác quan khác nhau để xem xét lá, hoa, quả... và thảo luận về đặc điểm của đối tượng.', 'Phần ba › D › II › a) › 1 › 1.2', 20);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '1', 'Xem xét và tìm hiểu đặc điểm của các sự vật, hiện tượng', '1.3', 'Làm thử nghiệm và sử dụng công cụ đơn giản để quan sát, so sánh, dự đoán, nhận xét và thảo luận. Ví dụ: Thử nghiệm gieo hạt/trồng cây được tưới nước và không tưới, theo dõi và so sánh sự phát triển.', 'Phần ba › D › II › a) › 1 › 1.3', 21);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '1', 'Xem xét và tìm hiểu đặc điểm của các sự vật, hiện tượng', '1.4', 'Thu thập thông tin về đối tượng bằng nhiều cách khác nhau: xem sách tranh ảnh, băng hình, trò chuyện và thảo luận.', 'Phần ba › D › II › a) › 1 › 1.4', 22);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '1', 'Xem xét và tìm hiểu đặc điểm của các sự vật, hiện tượng', '1.5', 'Phân loại các đối tượng theo những dấu hiệu khác nhau.', 'Phần ba › D › II › a) › 1 › 1.5', 23);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá khoa học', '2', 'Nhận biết mối quan hệ đơn giản của sự vật, hiện tượng và giải quyết vấn đề đơn giản', '2.1', 'Nhận xét được mối quan hệ đơn giản của sự vật, hiện tượng. Ví dụ: “Nắp cốc có những giọt nước do nước nóng bốc hơi”.', 'Phần ba › D › II › a) › 2 › 2.1', 24);
