INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá xã hội', '1', 'Nhận biết bản thân, gia đình, trường lớp mầm non và cộng đồng', '1.2', 'Nói tên, tuổi, giới tính, công việc hàng ngày của các thành viên trong gia đình khi được hỏi, trò chuyện, xem ảnh về gia đình.', 'Phần ba › D › II › c) › 1 › 1.2', 43);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá xã hội', '1', 'Nhận biết bản thân, gia đình, trường lớp mầm non và cộng đồng', '1.3', 'Nói địa chỉ gia đình mình (số nhà, đường phố/thôn, xóm), số điện thoại (nếu có)… khi được hỏi, trò chuyện.', 'Phần ba › D › II › c) › 1 › 1.3', 44);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá xã hội', '1', 'Nhận biết bản thân, gia đình, trường lớp mầm non và cộng đồng', '1.4', 'Nói tên, địa chỉ và mô tả một số đặc điểm nổi bật của trường, lớp khi được hỏi, trò chuyện.', 'Phần ba › D › II › c) › 1 › 1.4', 45);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá xã hội', '1', 'Nhận biết bản thân, gia đình, trường lớp mầm non và cộng đồng', '1.5', 'Nói tên, công việc của cô giáo và các bác công nhân viên trong trường khi được hỏi, trò chuyện.', 'Phần ba › D › II › c) › 1 › 1.5', 46);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá xã hội', '1', 'Nhận biết bản thân, gia đình, trường lớp mầm non và cộng đồng', '1.6', 'Nói họ tên và đặc điểm của các bạn trong lớp khi được hỏi, trò chuyện.', 'Phần ba › D › II › c) › 1 › 1.6', 47);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá xã hội', '2', 'Nhận biết một số nghề phổ biến và nghề truyền thống ở địa phương', NULL, 'Nói đặc điểm và sự khác nhau của một số nghề. Ví dụ: nói “Nghề nông làm ra lúa gạo, nghề xây dựng xây nên những ngôi nhà mới ...”', 'Phần ba › D › II › c) › 2', 48);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá xã hội', '3', 'Nhận biết một số lễ hội và danh lam, thắng cảnh', '3.1', 'Kể tên một số lễ hội và nói về hoạt động nổi bật của những dịp lễ hội. Ví dụ nói: “Ngày Quốc khánh (ngày 02/9) cả phố em treo cờ, bố mẹ được nghỉ làm và cho em đi chơi công viên…”.', 'Phần ba › D › II › c) › 3 › 3.1', 49);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển nhận thức'), 'Khám phá xã hội', '3', 'Nhận biết một số lễ hội và danh lam, thắng cảnh', '3.2', 'Kể tên và nêu một vài nét đặc trưng của danh lam, thắng cảnh, di tích lịch sử của quê hương, đất nước.', 'Phần ba › D › II › c) › 3 › 3.2', 50);
