INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-4'), (SELECT id FROM edu_domains WHERE name = 'Phát triển ngôn ngữ'), NULL, '3', 'Làm quen với việc đọc - viết', '3.2', 'Mô tả hành động của các nhân vật trong tranh.', 'Phần ba › D › III › 3 › 3.2', 63);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-4'), (SELECT id FROM edu_domains WHERE name = 'Phát triển ngôn ngữ'), NULL, '3', 'Làm quen với việc đọc - viết', '3.3', 'Cầm sách đúng chiều và giở từng trang để xem tranh ảnh. “đọc” sách theo tranh minh họa (“đọc vẹt”).', 'Phần ba › D › III › 3 › 3.3', 64);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-4'), (SELECT id FROM edu_domains WHERE name = 'Phát triển ngôn ngữ'), NULL, '3', 'Làm quen với việc đọc - viết', '3.4', 'Nhận ra ký hiệu thông thường trong cuộc sống: nhà vệ sinh, cấm lửa, nơi nguy hiểm,..', 'Phần ba › D › III › 3 › 3.4', 65);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-4'), (SELECT id FROM edu_domains WHERE name = 'Phát triển ngôn ngữ'), NULL, '3', 'Làm quen với việc đọc - viết', '3.5', 'Sử dụng ký hiệu để “viết”: tên, làm vé tàu, thiệp chúc mừng,..', 'Phần ba › D › III › 3 › 3.5', 66);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển ngôn ngữ'), NULL, '1', 'Nghe hiểu lời nói', '1.1', 'Thực hiện được các yêu cầu trong hoạt động tập thể, ví dụ: “Các bạn có tên bắt đầu bằng chữ cái T đứng sang bên phải, các bạn có tên bắt đầu bằng chữ H đứng sang bên trái”.', 'Phần ba › D › III › 1 › 1.1', 51);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển ngôn ngữ'), NULL, '1', 'Nghe hiểu lời nói', '1.2', 'Hiểu nghĩa từ khái quát: phương tiện giao thông, động vật, thực vật, đồ dùng (đồ dùng gia đình, đồ dùng học tập,...).', 'Phần ba › D › III › 1 › 1.2', 52);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển ngôn ngữ'), NULL, '1', 'Nghe hiểu lời nói', '1.3', 'Lắng nghe và nhận xét ý kiến của người đối thoại.', 'Phần ba › D › III › 1 › 1.3', 53);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển ngôn ngữ'), NULL, '2', 'Sử dụng lời nói trong cuộc sống hàng ngày', '2.1', 'Kể rõ ràng, có trình tự về sự việc, hiện tượng nào đó để người nghe có thể hiểu được.', 'Phần ba › D › III › 2 › 2.1', 54);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển ngôn ngữ'), NULL, '2', 'Sử dụng lời nói trong cuộc sống hàng ngày', '2.2', 'Sử dụng các từ chỉ sự vật, hoạt động, đặc điểm,… phù hợp với ngữ cảnh.', 'Phần ba › D › III › 2 › 2.2', 55);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển ngôn ngữ'), NULL, '2', 'Sử dụng lời nói trong cuộc sống hàng ngày', '2.3', 'Dùng được câu đơn, câu ghép, câu khẳng định, câu phủ định, câu mệnh lệnh,…', 'Phần ba › D › III › 2 › 2.3', 56);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển ngôn ngữ'), NULL, '2', 'Sử dụng lời nói trong cuộc sống hàng ngày', '2.4', 'Miêu tả sự việc với một số thông tin về hành động, tính cách, trạng thái,... của nhân vật.', 'Phần ba › D › III › 2 › 2.4', 57);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển ngôn ngữ'), NULL, '2', 'Sử dụng lời nói trong cuộc sống hàng ngày', '2.5', 'Đọc biểu cảm bài thơ, đồng dao, cao dao...', 'Phần ba › D › III › 2 › 2.5', 58);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển ngôn ngữ'), NULL, '2', 'Sử dụng lời nói trong cuộc sống hàng ngày', '2.6', 'Kể có thay đổi một vài tình tiết như thay tên nhân vật, thay đổi kết thúc, thêm bớt sự kiện... trong nội dung truyện.', 'Phần ba › D › III › 2 › 2.6', 59);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển ngôn ngữ'), NULL, '2', 'Sử dụng lời nói trong cuộc sống hàng ngày', '2.7', 'Đóng được vai của nhân vật trong truyện.', 'Phần ba › D › III › 2 › 2.7', 60);
