INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển tình cảm và kỹ năng xã hội'), NULL, '4', 'Hành vi và quy tắc ứng xử xã hội', '4.1', 'Thực hiện được một số quy định ở lớp, gia đình và nơi công cộng: Sau khi chơi cất đồ chơi vào nơi quy định, không làm ồn nơi công cộng, vâng lời ông bà, bố mẹ, anh chị, muốn đi chơi phải xin phép.', 'Phần ba › D › IV › 4 › 4.1', 82);
