INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-3'), (SELECT id FROM edu_domains WHERE name = 'Phát triển thẩm mỹ'), NULL, '1', 'Cảm nhận và thể hiện cảm xúc trước vẻ đẹp của thiên nhiên, cuộc sống và các tác phẩm nghệ thuật', '1.1', 'Vui sướng, vỗ tay, nói lên cảm nhận của mình khi nghe các âm thanh gợi cảm và ngắm nhìn vẻ đẹp nổi bật của các sự vật, hiện tượng.', 'Phần ba › D › V › 1 › 1.1', 71);
