INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-4'), (SELECT id FROM edu_domains WHERE name = 'Phát triển thẩm mỹ'), NULL, '1', 'Cảm nhận và thể hiện cảm xúc trước vẻ đẹp của thiên nhiên, cuộc sống và các tác phẩm nghệ thuật', '1.1', 'Vui sướng, vỗ tay, làm động tác mô phỏng và sử dụng các từ gợi cảm nói lên cảm xúc của mình khi nghe các âm thanh gợi cảm và ngắm nhìn vẻ đẹp của các sự vật, hiện tượng.', 'Phần ba › D › V › 1 › 1.1', 85);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-4'), (SELECT id FROM edu_domains WHERE name = 'Phát triển thẩm mỹ'), NULL, '1', 'Cảm nhận và thể hiện cảm xúc trước vẻ đẹp của thiên nhiên, cuộc sống và các tác phẩm nghệ thuật', '1.2', 'Chú ý nghe, thích thú (hát, vỗ tay, nhún nhảy, lắc lư) theo bài hát, bản nhạc; thích nghe và đọc thơ, đồng dao, ca dao, tục ngữ; thích nghe và kể câu chuyện.', 'Phần ba › D › V › 1 › 1.2', 86);
INSERT INTO edu_curriculum_goals (source_id, age_group_id, domain_id, sub_domain, group_no, group_text, goal_no, goal_text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-4'), (SELECT id FROM edu_domains WHERE name = 'Phát triển thẩm mỹ'), NULL, '1', 'Cảm nhận và thể hiện cảm xúc trước vẻ đẹp của thiên nhiên, cuộc sống và các tác phẩm nghệ thuật', '1.3', 'Thích thú, ngắm nhìn, chỉ, sờ và sử dụng các từ gợi cảm nói lên cảm xúc của mình (về màu sắc, hình dáng…) của các tác phẩm tạo hình.', 'Phần ba › D › V › 1 › 1.3', 87);
