INSERT INTO edu_curriculum_contents (source_id, age_group_id, domain_id, sub_domain, category_no, category, label, text, section_ref, sort_order) VALUES ((SELECT id FROM edu_curriculum_sources WHERE code = 'VBHN-01-2021-GDMN'), (SELECT id FROM age_groups WHERE code = 'ag-5'), (SELECT id FROM edu_domains WHERE name = 'Phát triển thể chất'), 'Phát triển vận động', '1', 'Động tác phát triển các nhóm cơ và hô hấp', 'Lưng, bụng, lườn', 'Ngửa người ra sau kết hợp tay giơ lên cao, chân bước sang phải, sang trái.', 'Phần ba › C › I › a) › 1', 3);
